import '../App.css';
import BotonMood from '../componentes/BotonMood';
import SliderAnios from '../componentes/SliderAnios';
import WizardSidebar from '../componentes/WizardSidebar';
import { useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import moodTristeJoker from '../assets/mood-triste-joker.png';
import moodNostalgicoNoir from '../assets/mood-nostalgico-noir.png';
import moodRelajadoAtardecer from '../assets/mood-relajado-atardecer.png';
import moodAnsisoThiller from '../assets/mood-ansioso-thriller.png';
import moodFelizMusica from '../assets/mood-feliz-musica.png';
import moodMotivadoImpulso from '../assets/mood-motivado-impulso.png';
import moodEnfadadoFuria from '../assets/mood-enfadado-furia.png';
import moodEmocionadoAventura from '../assets/mood-emocionado-aventura.png';
import generoAccion from '../assets/genero-accion.png';
import generoAventura from '../assets/genero-aventura.png';
import generoAnimacion from '../assets/genero-animacion.png';
import generoComedia from '../assets/genero-comedia.png';
import generoCrimen from '../assets/genero-crimen.png';
import generoDrama from '../assets/genero-drama.png';
import generoFamilia from '../assets/genero-familia.png';
import generoFantasia from '../assets/genero-fantasia.png';
import generoTerror from '../assets/genero-terror.png';
import generoMusical from '../assets/genero-musical.png';
import generoMisterio from '../assets/genero-misterio.png';
import generoRomance from '../assets/genero-romance.png';
import generoCienciaFiccion from '../assets/genero-ciencia-ficcion.png';
import generoThriller from '../assets/genero-thriller.png';
import generoBelica from '../assets/genero-belica.png';
import generoWestern from '../assets/genero-western.png';

const MOOD_CARD_BACKGROUNDS = {
  triste: moodTristeJoker,
  nostalgico: moodNostalgicoNoir,
  relajado: moodRelajadoAtardecer,
  ansioso: moodAnsisoThiller,
  feliz: moodFelizMusica,
  motivado: moodMotivadoImpulso,
  enojado: moodEnfadadoFuria,
  emocionado: moodEmocionadoAventura
};

const GENERO_CARD_BACKGROUNDS = {
  accion: generoAccion,
  aventura: generoAventura,
  animacion: generoAnimacion,
  comedia: generoComedia,
  crimen: generoCrimen,
  drama: generoDrama,
  familia: generoFamilia,
  fantasia: generoFantasia,
  terror: generoTerror,
  musical: generoMusical,
  misterio: generoMisterio,
  romance: generoRomance,
  'ciencia-ficcion': generoCienciaFiccion,
  thriller: generoThriller,
  belica: generoBelica,
  western: generoWestern
};

function Cuestionario() {
  const location = useLocation();
  const navigate = useNavigate();
  const { currentUser } = useAuth();
  const presetQuestionnaire = location.state?.questionnaire;
  const displayName = (currentUser?.name || currentUser?.username || 'Perfil').split(' ')[0];
  const avatarInitial = displayName.charAt(0).toUpperCase() || 'M';
  
  // Estado para controlar en qué paso estamos (1, 2, 3, 4)
  const [pasoActual, setPasoActual] = useState(1);
  
  // Estados para las respuestas
  const [moodsSeleccionados, setMoodsSeleccionados] = useState(presetQuestionnaire?.moods || []);
  const [avisoMood, setAvisoMood] = useState('');
  const [aniosSeleccionados, setAniosSeleccionados] = useState(presetQuestionnaire?.anios || { min: 1980, max: 2026 });
  const [duracionSeleccionada, setDuracionSeleccionada] = useState(presetQuestionnaire?.duracion || '');
  const [generosSeleccionados, setGenerosSeleccionados] = useState(presetQuestionnaire?.generos || []); // ← AHORA ES ARRAY

  useEffect(() => {
    if (!presetQuestionnaire) {
      return;
    }

    setMoodsSeleccionados(presetQuestionnaire.moods || []);
    setAniosSeleccionados(presetQuestionnaire.anios || { min: 1980, max: 2026 });
    setDuracionSeleccionada(presetQuestionnaire.duracion || '');
    setGenerosSeleccionados(presetQuestionnaire.generos || []);
    setPasoActual(1);
    setAvisoMood('');
  }, [presetQuestionnaire]);

  // Si no hay usuario autenticado, mostrar modal
  if (!currentUser) {
    return (
      <div className="login-required-modal" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', background: 'var(--bg, #050b14)' }}>
        <div style={{ textAlign: 'center', color: '#f5f7fb', maxWidth: '400px', padding: '40px 20px' }}>
          <h1 style={{ fontSize: '1.8rem', marginBottom: '16px' }}>Inicia sesión para continuar</h1>
          <p style={{ color: 'rgba(202, 219, 232, 0.7)', fontSize: '1rem', lineHeight: '1.5', marginBottom: '28px' }}>
            Para acceder al cuestionario de mood y obtener recomendaciones personalizadas, necesitas iniciar sesión.
          </p>
          <button
            onClick={() => navigate('/login', { state: { from: '/cuestionario' } })}
            style={{
              background: 'linear-gradient(135deg, #34d7dc 0%, #1abcc7 100%)',
              color: '#04141a',
              border: 'none',
              padding: '13px 28px',
              borderRadius: '999px',
              fontWeight: 700,
              cursor: 'pointer',
              fontSize: '1rem',
              marginRight: '12px'
            }}
          >
            Iniciar sesión
          </button>
          <button
            onClick={() => navigate('/')}
            style={{
              background: 'rgba(9, 16, 25, 0.5)',
              color: '#f3f7fb',
              border: '1px solid rgba(255, 255, 255, 0.12)',
              padding: '13px 28px',
              borderRadius: '999px',
              fontWeight: 700,
              cursor: 'pointer',
              fontSize: '1rem',
              backdropFilter: 'blur(8px)'
            }}
          >
            Volver al inicio
          </button>
        </div>
      </div>
    );
  }

  const titulosPaso = {
    1: 'Mood',
    2: 'Epoca',
    3: 'Duracion',
    4: 'Generos'
  };

  // Datos de cada pregunta
  const listaMoods = [
    { iconName: 'triste', texto: 'Triste', backgroundImage: MOOD_CARD_BACKGROUNDS.triste },
    { iconName: 'nostalgico', texto: 'Nostálgico', backgroundImage: MOOD_CARD_BACKGROUNDS.nostalgico },
    { iconName: 'relajado', texto: 'Relajado', backgroundImage: MOOD_CARD_BACKGROUNDS.relajado },
    { iconName: 'ansioso', texto: 'Ansioso', backgroundImage: MOOD_CARD_BACKGROUNDS.ansioso },
    { iconName: 'feliz', texto: 'Feliz', backgroundImage: MOOD_CARD_BACKGROUNDS.feliz },
    { iconName: 'motivado', texto: 'Motivado', backgroundImage: MOOD_CARD_BACKGROUNDS.motivado },
    { iconName: 'enojado', texto: 'Enfadado', backgroundImage: MOOD_CARD_BACKGROUNDS.enojado },
    { iconName: 'emocionado', texto: 'Emocionado', backgroundImage: MOOD_CARD_BACKGROUNDS.emocionado }
  ];

  const listaDuraciones = [
    { iconName: 'corta', texto: 'Corta', detalle: '< 90 min' },
    { iconName: 'media', texto: 'Media', detalle: '90-120 min' },
    { iconName: 'larga', texto: 'Larga', detalle: '> 120 min' }
  ];

  const presetsAnios = [
    { label: 'Ultimos 5 años', min: 2021, max: 2026 },
    { label: '90s', min: 1990, max: 1999 },
    { label: '2000-2010', min: 2000, max: 2010 },
    { label: 'Clasicos', min: 1950, max: 1985 }
  ];

  const listaGeneros = [
    { iconName: 'accion', texto: 'Acción', backgroundImage: GENERO_CARD_BACKGROUNDS.accion },
    { iconName: 'aventura', texto: 'Aventura', backgroundImage: GENERO_CARD_BACKGROUNDS.aventura },
    { iconName: 'animacion', texto: 'Animación', backgroundImage: GENERO_CARD_BACKGROUNDS.animacion },
    { iconName: 'comedia', texto: 'Comedia', backgroundImage: GENERO_CARD_BACKGROUNDS.comedia },
    { iconName: 'crimen', texto: 'Crimen', backgroundImage: GENERO_CARD_BACKGROUNDS.crimen },
    { iconName: 'drama', texto: 'Drama', backgroundImage: GENERO_CARD_BACKGROUNDS.drama },
    { iconName: 'familia', texto: 'Familia', backgroundImage: GENERO_CARD_BACKGROUNDS.familia },
    { iconName: 'fantasia', texto: 'Fantasía', backgroundImage: GENERO_CARD_BACKGROUNDS.fantasia },
    { iconName: 'terror', texto: 'Terror', backgroundImage: GENERO_CARD_BACKGROUNDS.terror },
    { iconName: 'musical', texto: 'Musical', backgroundImage: GENERO_CARD_BACKGROUNDS.musical },
    { iconName: 'misterio', texto: 'Misterio', backgroundImage: GENERO_CARD_BACKGROUNDS.misterio },
    { iconName: 'romance', texto: 'Romance', backgroundImage: GENERO_CARD_BACKGROUNDS.romance },
    { iconName: 'ciencia-ficcion', texto: 'Ciencia Ficción', backgroundImage: GENERO_CARD_BACKGROUNDS['ciencia-ficcion'] },
    { iconName: 'thriller', texto: 'Thriller', backgroundImage: GENERO_CARD_BACKGROUNDS.thriller },
    { iconName: 'belica', texto: 'Bélica', backgroundImage: GENERO_CARD_BACKGROUNDS.belica },
    { iconName: 'western', texto: 'Western', backgroundImage: GENERO_CARD_BACKGROUNDS.western }
  ];

  // Función para seleccionar/deseleccionar géneros (toggle)
  function toggleGenero(genero) {
    if (generosSeleccionados.includes(genero)) {
      // Ya está seleccionado → deseleccionar
      setGenerosSeleccionados(generosSeleccionados.filter(g => g !== genero));
    } else {
      // No está seleccionado → seleccionar
      setGenerosSeleccionados([...generosSeleccionados, genero]);
    }
  }

  // Función para deseleccionar todos los géneros
  function deseleccionarTodos() {
    setGenerosSeleccionados([]);
  }

  // Funciones de navegación
  function irSiguiente() {
    if (pasoActual < 4) {
      setPasoActual(pasoActual + 1);
    } else {
      const questionnaire = {
        moods: moodsSeleccionados,
        anios: aniosSeleccionados,
        duracion: duracionSeleccionada,
        generos: generosSeleccionados,
      };

      localStorage.setItem('movimood-cuestionario', JSON.stringify(questionnaire));
      navigate('/resultados', { state: { questionnaire } });
    }
  }

  function irAtras() {
    if (pasoActual > 1) {
      setPasoActual(pasoActual - 1);
    }
  }

  function toggleMood(mood) {
    if (moodsSeleccionados.includes(mood)) {
      setMoodsSeleccionados(moodsSeleccionados.filter((m) => m !== mood));
      setAvisoMood('');
    } else if (moodsSeleccionados.length < 2) {
      setMoodsSeleccionados([...moodsSeleccionados, mood]);
      setAvisoMood('');
    } else {
      setAvisoMood('Puedes seleccionar como maximo 2 emociones.');
      return;
    }
  }

  function aplicarPresetAnios(min, max) {
    setAniosSeleccionados({ min, max });
  }

  function getTextoRangoAnios() {
    const rango = aniosSeleccionados.max - aniosSeleccionados.min;

    if (rango <= 2) {
      return `Rango muy especifico (${aniosSeleccionados.min}-${aniosSeleccionados.max}). Te mostraremos recomendaciones muy concretas.`;
    }

    if (rango <= 8) {
      return `Rango definido (${aniosSeleccionados.min}-${aniosSeleccionados.max}). Buen equilibrio entre precision y variedad.`;
    }

    return `Te sugeriremos cine de ${aniosSeleccionados.min} a ${aniosSeleccionados.max} con una variedad amplia de titulos.`;
  }

  function getTextoGeneros() {
    if (generosSeleccionados.length === 0) {
      return 'Elige al menos 1 genero para personalizar mejor tus recomendaciones.';
    }

    if (generosSeleccionados.length === 1) {
      return 'Buen inicio. Si anades uno mas, afinaremos mejor el resultado.';
    }

    if (generosSeleccionados.length <= 4) {
      return 'Seleccion ideal: equilibrio perfecto entre precision y variedad.';
    }

    return 'Has elegido muchos generos. Priorizaremos los que mejor encajen con tu mood.';
  }

  // Verificar si puede avanzar (respuesta seleccionada)
  function puedeAvanzar() {
    switch(pasoActual) {
      case 1: return moodsSeleccionados.length >= 1;
      case 2: return true; // Slider siempre tiene valores
      case 3: return duracionSeleccionada !== '';
      case 4: return generosSeleccionados.length > 0; // Al menos 1 género
      default: return false;
    }
  }

  return (
    <div className="cuestionario-page">
      <WizardSidebar activeLabel="Cuestionario" hideLinks={['Mi lista', 'Resultados']} />

      <main className="cuestionario-main">
        {/* Barra de progreso */}
        <div className="wizard-progreso">
          <div className="progreso-barra">
            <div 
              className="progreso-relleno" 
              style={{ width: `${(pasoActual / 4) * 100}%` }}
            ></div>
          </div>
          <div className="wizard-progreso-meta">
            <p className="progreso-texto">Paso {pasoActual} de 4</p>
          </div>
        </div>

        {/* Perfil de usuario - Posicionado arriba a la derecha */}
        {currentUser && (
          <button
            type="button"
            className="wizard-user-chip-fixed"
            onClick={() => navigate('/perfil')}
            aria-label="Ir a mi perfil"
          >
            {currentUser.avatar ? (
              <img className="wizard-user-avatar" src={currentUser.avatar} alt={`Avatar de ${displayName}`} />
            ) : (
              <span className="wizard-user-avatar wizard-user-avatar-fallback" aria-hidden="true">{avatarInitial}</span>
            )}
            <span className="wizard-user-name">{displayName}</span>
            <span className="wizard-user-caret" aria-hidden="true">▾</span>
          </button>
        )}

        {/* Contenedor del paso actual con animación */}
        <div className={`wizard-contenedor ${pasoActual === 1 || pasoActual === 2 || pasoActual === 3 || pasoActual === 4 ? 'wizard-contenedor--sin-card' : ''}`} key={pasoActual}>
        <div className="wizard-step-chip-wrap">
          <span className="wizard-step-chip">PASO {pasoActual} • {titulosPaso[pasoActual]}</span>
        </div>
        
        {/* PASO 1: MOOD */}
        {pasoActual === 1 && (
          <div className="wizard-paso">
            <h2>¿Cómo te sientes <span className="wizard-title-accent">hoy?</span></h2>
            <p className="wizard-subtitulo">Selecciona 1 o 2 emociones</p>
            <p className="mood-selector-meta">Seleccionadas: {moodsSeleccionados.length}/2</p>
           
            {avisoMood && <p className="mood-selector-warning">{avisoMood}</p>}
            <div className="contenedor-botones moods-strip">
              {listaMoods.map((mood) => (
                <BotonMood 
                  key={mood.texto}
                  iconName={mood.iconName}
                  texto={mood.texto}
                  backgroundImage={mood.backgroundImage}
                  onClick={() => toggleMood(mood.texto)}
                  seleccionado={moodsSeleccionados.includes(mood.texto)}
                />
              ))}
            </div>
          </div>
        )}

        {/* PASO 2: AÑOS */}
        {pasoActual === 2 && (
          <div className="wizard-paso">
            <h2>¿Qué <span className="wizard-title-accent">época</span> te apetece hoy?</h2>
            <p className="wizard-subtitulo">Puedes mover el rango o usar un preset rapido</p>

            <div className="anios-presets" role="group" aria-label="Presets de años">
              {presetsAnios.map((preset) => {
                const activo = aniosSeleccionados.min === preset.min && aniosSeleccionados.max === preset.max;
                return (
                  <button
                    key={preset.label}
                    type="button"
                    className={`anio-preset-btn ${activo ? 'activo' : ''}`}
                    onClick={() => aplicarPresetAnios(preset.min, preset.max)}
                  >
                    {preset.label}
                  </button>
                );
              })}
            </div>

            <SliderAnios 
              onCambio={setAniosSeleccionados} 
              valoresIniciales={aniosSeleccionados}
            />

            <p className="anios-contexto">{getTextoRangoAnios()}</p>
          </div>
        )}

        {/* PASO 3: DURACIÓN */}
        {pasoActual === 3 && (
          <div className="wizard-paso">
            <h2>¿Cuánto quieres que dure la película?</h2>
            <p className="wizard-subtitulo">Elige la duracion que te apetece ver hoy</p>
            <div className="contenedor-botones duracion-grid" role="group" aria-label="Opciones de duración">
              {listaDuraciones.map((duracion) => (
                <BotonMood 
                  key={duracion.texto}
                  iconName={duracion.iconName}
                  texto={duracion.texto}
                  detalle={duracion.detalle}
                  onClick={() => setDuracionSeleccionada(duracion.texto)}
                  seleccionado={duracionSeleccionada === duracion.texto}
                />
              ))}
            </div>
          </div>
        )}

        {/* PASO 4: GÉNERO (SELECCIÓN MÚLTIPLE) */}
        {pasoActual === 4 && (
          <div className="wizard-paso">
            <h2>¿Qué géneros te apetecen?</h2>
            <p className="wizard-subtitulo">Elige los generos que te apetecen hoy</p>
            
            {/* Contador y botón deseleccionar */}
            <div className="generos-info">
              <p className="generos-contador">
                {generosSeleccionados.length === 0 
                  ? 'No has seleccionado ningún género' 
                  : `Has seleccionado ${generosSeleccionados.length} género${generosSeleccionados.length > 1 ? 's' : ''}`
                }
              </p>
              <span className="generos-recomendado">Recomendado: 2-4</span>
              {generosSeleccionados.length > 0 && (
                <button className="boton-deseleccionar" onClick={deseleccionarTodos}>
                  Deseleccionar todos
                </button>
              )}
            </div>

            <div className="contenedor-botones generos-grid">
              {listaGeneros.map((genero) => (
                <BotonMood 
                  key={genero.texto}
                  iconName={genero.iconName}
                  texto={genero.texto}
                  backgroundImage={genero.backgroundImage}
                  onClick={() => toggleGenero(genero.texto)}
                  seleccionado={generosSeleccionados.includes(genero.texto)}
                />
              ))}
            </div>

            {/* Sugerencia */}
            <p className="generos-sugerencia">
              {getTextoGeneros()}
            </p>
          </div>
        )}

        {/* Botones de navegación */}
        <div className="wizard-botones">
          {pasoActual > 1 && (
            <button className="boton-wizard boton-atras" onClick={irAtras}>
              ← Atrás
            </button>
          )}
          
          <button 
            className="boton-wizard boton-siguiente" 
            onClick={irSiguiente}
            disabled={!puedeAvanzar()}
          >
            {pasoActual === 4 ? '🎥 Ver Películas' : 'Siguiente →'}
          </button>
        </div>
        </div>
        
      </main>
    </div>
  );
}

export default Cuestionario;